package app.dopamine.domain.content

import app.dopamine.BuildConfig
import app.dopamine.ui.math.MathParser
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The app and the content repo must agree. `contract.json` is generated by the content repo
 * (tools/build_contract.py) and copied here by tools/sync_contract.sh. If this test fails after a sync,
 * the app has to learn the new content (or the content repo changed by mistake).
 */
class ContractTest {
    private val contract: JsonObject = Json.parseToJsonElement(
        javaClass.getResourceAsStream("/contract.json")!!.readBytes().decodeToString(),
    ).jsonObject

    private fun kinds(key: String): Map<String, Int> = contract[key]!!.jsonObject.mapValues { it.value.jsonPrimitive.int }

    @Test fun versionsMatch() {
        assertEquals(ContentContract.CONTRACT_VERSION, contract["contractVersion"]!!.jsonPrimitive.int)
        assertEquals("ContentContract.APP_VERSION must equal versionCode", BuildConfig.VERSION_CODE, ContentContract.APP_VERSION)
    }

    @Test fun kindsMatch() {
        assertEquals(kinds("questionTypes"), ContentContract.QUESTION_TYPES)
        assertEquals(kinds("pageKinds"), ContentContract.PAGE_KINDS)
        assertEquals(kinds("noteKinds"), ContentContract.NOTE_KINDS)
    }

    @Test fun mathCommandsMatch() {
        val fromContract = contract["latexCommands"]!!.jsonArray.map { it.jsonPrimitive.content }.toSet()
        assertEquals(fromContract, MathParser.supportedCommands)
    }

    @Test fun limitsMatch() {
        val l = contract["limits"]!!.jsonObject
        fun i(k: String) = l[k]!!.jsonPrimitive.int
        val L = ContentContract.Limits
        assertEquals(L.ID_PATTERN, l["idPattern"]!!.jsonPrimitive.content)
        val expected = mapOf(
            "titleMax" to L.TITLE_MAX, "xpMin" to L.XP_MIN, "xpMax" to L.XP_MAX,
            "questionsMin" to L.QUESTIONS_MIN, "questionsMax" to L.QUESTIONS_MAX, "textMax" to L.TEXT_MAX,
            "choicesMin" to L.CHOICES_MIN, "choicesMax" to L.CHOICES_MAX, "answerIndexMax" to L.ANSWER_INDEX_MAX,
            "acceptedMin" to L.ACCEPTED_MIN, "acceptedMax" to L.ACCEPTED_MAX, "acceptedItemMax" to L.ACCEPTED_ITEM_MAX,
            "pairsMin" to L.PAIRS_MIN, "pairsMax" to L.PAIRS_MAX, "stepsMin" to L.STEPS_MIN, "stepsMax" to L.STEPS_MAX,
            "learnMax" to L.LEARN_MAX, "pageTitleMax" to L.PAGE_TITLE_MAX,
            "exampleStepsMin" to L.EXAMPLE_STEPS_MIN, "exampleStepsMax" to L.EXAMPLE_STEPS_MAX,
            "notesBlocksMax" to L.NOTES_BLOCKS_MAX, "noteItemsMax" to L.NOTE_ITEMS_MAX,
            "summaryMax" to L.SUMMARY_MAX, "outcomesMax" to L.OUTCOMES_MAX, "requirementsMax" to L.REQUIREMENTS_MAX,
            "minutesMax" to L.MINUTES_MAX, "codeMax" to L.CODE_MAX, "codeLines" to L.CODE_LINES, "codeWidth" to L.CODE_WIDTH,
        )
        // Every limit the contract lists is checked, and every one we check is in the contract.
        assertEquals((l.keys - "idPattern"), expected.keys)
        expected.forEach { (k, v) -> assertEquals("limit $k", i(k), v) }
    }
}
